// 자동 생성 파일 — firmware/tools/gen_font_js.py. 직접 수정하지 말 것
// 펌웨어(font8x8.h / font8x8_kr.h)와 동일한 비트맵 테이블.
// 글자당 8바이트, 바이트 = 세로 한 컬럼, bit0 = 맨 위 LED.
"use strict";
(function () {
  function unb64(s) {
    const bin = atob(s);
    const u8 = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
    return u8;
  }
  // ASCII 0x20~0x7E (95자)
  window.FONT8 = unb64("");
  // 한글 음절 U+AC00~U+D7A3 (11172자). 인덱스 = 코드포인트 - 0xAC00
  window.FONT8_KR = unb64("");
})();
